  async function mappingPage(bundle,resource){const launchNative=!bundle.selectedNodeIds;bundle.editorContext||=crypto.randomUUID();app.mapping={bundle,resource};const api=bundle.api||{},rows=[];for(const [nodeId,node]of Object.entries(api))for(const [key,value]of Object.entries(node.inputs||{})){if(Array.isArray(value))continue;const m=bundle.mapping?.inputs?.find(i=>String(i.nodeId)===nodeId&&i.input===key);const option=(items,selected)=>items.map(v=>'<option value="'+esc(v)+'"'+(v===selected?' selected':'')+'>'+esc(v)+'</option>').join('');rows.push('<tr data-map-node="'+esc(nodeId)+'" data-map-input="'+esc(key)+'"'+(bundle.selectedNodeIds?.includes(nodeId)?' class="native-selected"':'')+'><td><input type="checkbox" data-map-enable '+(m?'checked':'')+'></td><td>'+esc(nodeId)+' · '+esc(node._meta?.title||node.class_type)+'<small>'+esc(key)+'</small></td><td><input data-map-id value="'+esc(m?.id||key)+'"><input data-map-label placeholder="显示名称" value="'+esc(m?.label||key)+'"></td><td><select data-map-source>'+option(['parameter','prompt','reference','constant'],m?.source||'parameter')+'</select><select data-map-type>'+option(['string','number','integer','boolean'],m?.type||typeof value)+'</select></td><td><input data-map-default value="'+esc(m?.source==='constant'?(m?.value??value):(m?.default??value))+'"><div class="row"><input data-map-min type="number" placeholder="最小" value="'+esc(m?.min??'')+'"><input data-map-max type="number" placeholder="最大" value="'+esc(m?.max??'')+'"></div></td><td><select data-map-media>'+option(['','image','video','audio','text'],m?.mediaType||'')+'</select><label>索引<input data-map-index type="number" min="0" max="63" value="'+esc(m?.index||0)+'"></label><label><input type="checkbox" data-map-multiple '+(m?.multiple?'checked':'')+'>多素材</label><label><input type="checkbox" data-map-required '+(m?.required?'checked':'')+'>必填</label></td></tr>');}
    const outputs=bundle.mapping?.outputs||[];show('工作流与公开参数映射',form('mapping',input('name','工作流名称',resource?.name||'自定义工作流','text','required')+'<div class="row">'+btn('mapping-open-native','在 ComfyUI 画布选择节点和参数','workflow')+btn('native-convert','同步原生编辑器','check')+'</div>'+notice(resource?.defaultId?'正在编辑本机默认工作流：不会复制进画布或打包，请自行备份安装目录中的配套配置。':'在原生画布选择节点并公开参数，Ctrl+S 同步回此处，再保存工作流。高级表格仅用于核对；不覆盖导入原文件。')+'<details><summary>高级：核对输入与输出映射</summary><div class="table-scroll"><table class="mapping-table"><thead><tr><th>公开</th><th>节点 · 参数</th><th>固定标识／显示名称</th><th>来源／类型</th><th>默认／范围</th><th>素材端口／必填</th></tr></thead><tbody>'+rows.join('')+'</tbody></table></div><h3>输出与主预览</h3><div id="mapped-outputs">'+outputs.map(outputRow).join('')+'</div>'+btn('mapping-add-output','添加输出','plus')+'<details><summary>高级：输出配置 JSON</summary><textarea name="outputs" rows="5">'+esc(JSON.stringify(outputs,null,2))+'</textarea></details></details>'),'mapping');if(launchNative&&bundle.gui){try{const result=await D.nativeConvert(bundle.gui,{mapping:bundle.mapping,editorContext:bundle.editorContext});app.mapping.bundle={...bundle,...result};}catch(e){toast('原生映射画布未打开：'+e.message);}}}
  function outputRow(o={}){return '<div class="mapped-output row"><input data-out-id placeholder="固定标识" value="'+esc(o.id||'')+'"><input data-out-label placeholder="显示名称" value="'+esc(o.label||'')+'"><select data-out-node>'+Object.entries(app.mapping.bundle.api||{}).map(([id,n])=>'<option value="'+id+'"'+(String(o.nodeId)===id?' selected':'')+'>'+esc(id+' · '+(n._meta?.title||n.class_type))+'</option>').join('')+'</select><input data-out-key placeholder="返回字段，例如 images" value="'+esc(o.key||'')+'"><select data-out-type>'+['image','video','audio','text'].map(t=>'<option'+((o.type||o.mediaType)===t?' selected':'')+'>'+t+'</option>').join('')+'</select><label><input type="checkbox" data-out-primary '+(o.primary?'checked':'')+'>主预览</label><label><input type="checkbox" data-out-required '+(o.required!==false?'checked':'')+'>必需</label>'+btn('mapping-remove-output','×')+'</div>';}
