  async function diagnostics(nodeId){const data=await call('diagnostics.list');const tasks=nodeId?data.tasks.filter(t=>t.nodeId===nodeId):data.tasks;show('当前诊断','<div class="row">'+btn('export-diagnostics','导出脱敏诊断包','download')+btn('copy-diagnostics','复制本次日志','copy')+'</div><p class="muted">任务输入和私人聊天默认不附带诊断包。任务关键错误保留，素材不受日志清理影响。</p><div class="log">'+esc(JSON.stringify({logs:data.logs,tasks},null,2))+'</div>','diagnosis');app.diagnosticText=JSON.stringify({logs:data.logs,tasks},null,2);}
  async function lanPage(){const l=await call('lan.status');app.lan=l;show('局域网',C.nav('lan')+notice('每人只修改自己的内容；成员下载完整素材。停止共享不会收回已下载文件。')+'<h3>'+esc(l.identity?.name||'本机')+'</h3>'+input('localFingerprint','本机完整设备标识／公钥指纹',l.identity?.id||'尚未取得','text','readonly data-lan-fingerprint="local"')+input('hostFingerprint','当前协调者指纹',l.hostId||'暂无共享协调者','text','readonly data-lan-fingerprint="host"')+input('pinnedFingerprint','当前地址已固定的主机指纹',l.pinnedHostId||(l.mode==='hosting'?'本机发起共享，无需固定自己':'当前没有已固定主机'),'text','readonly data-lan-fingerprint="pinned"')+notice('加入前可通过可信渠道核对对方完整指纹。留空加入属于首次信任；成功连接后固定此地址的主机身份，变化时拒绝自动信任。')+'<div class="form-row"><label>会话状态</label><span>'+esc(l.mode)+' · '+l.assetsReady+'/'+l.assetsTotal+' 份素材就绪</span></div>'+(l.url?'<p class="path-text">'+esc(l.url)+'</p>':'')+'<div class="row">'+btn('lan-host-form','共享当前画布','share')+btn('lan-join-form','加入共享','link')+btn('lan-takeover','申请接管','workflow')+btn('lan-leave','离开会话')+btn('lan-stop','停止共享')+btn('execution-devices','执行设备','workflow')+'</div><h3>成员（完整设备标识）</h3>'+l.members.map(m=>'<div class="row member-row"><span class="member-dot" style="background:'+esc(m.color||'#777')+'"></span>'+esc(m.name)+'<small class="path-text">'+esc(m.id||'')+'</small></div>').join('')+notice('接管采用多数成员确认来避免双主。两台电脑中一台意外断线时，可保留本地完整副本另存独立项目；不谎称已完成安全接管。'),'lan');}
  async function executionPage(){const l=await call('lan.status'),data=await call('execution.offers');show('局域网执行设备',notice('共享画布与共享算力分别控制；设备所有者可暂停自己的设备，不能改写请求者的卡片。')+select('executionPauseProvider','本机调度来源',['comfyui','codex','image2','ollama','openai-compatible','runninghub'].map(provider=>[provider,sourceNames[provider]]),'comfyui')+'<div class="row">'+btn('execution-share','开放本机执行资源','plus')+btn('execution-pause','暂停所选来源后续任务',null,'data-paused="true"')+btn('execution-pause','恢复所选来源调度',null,'data-paused="false"')+'</div>'+notice('暂停仅影响本机所选来源的后续调度，不停止当前任务，也不会暂停其他来源。')+data.devices.map(d=>'<h3>'+esc(d.name)+(d.deviceId===l.identity.id?' · 本机':'')+'</h3>'+(d.reachable?'':'<p class="danger">暂时无法连接</p>')+'<div class="resource-cards">'+d.offers.map(o=>'<article class="resource-card"><div><h3>'+esc(o.name)+'</h3><p>'+esc(sourceNames[o.provider]||o.provider||'本地 ComfyUI')+' · '+esc(types[o.kind]?.name||o.kind)+' · '+(o.memberRestricted?'指定成员可用':'会话成员可用')+'</p>'+(d.deviceId===l.identity.id?btn('execution-stop','停止新请求',null,'data-id="'+o.id+'"'):'')+'</div></article>').join('')+'</div>').join(''),'execution');}
  async function executionChooser(nodeId){const n=graph.get(nodeId);if(!n||n.owner!=='me')throw new Error('请选择自己的生成节点');const data=await call('execution.offers'),identity=app.current.identity.id,kind=n.type==='custom'?(n.outputType||'image'):n.type;app.deviceChoices=data.devices.filter(d=>d.deviceId!==identity).flatMap(d=>d.offers.filter(o=>o.kind===kind&&o.enabled).map(o=>({...o,deviceId:d.deviceId,deviceName:d.name})));show('选择执行设备',btn('execution-local','使用本机来源','workflow','data-node="'+n.id+'"')+notice('远端只列出该成员主动开放且类型匹配的资源。远端任务的成果会完整保存进你的项目。')+'<div class="resource-cards">'+app.deviceChoices.map(o=>'<article class="resource-card"><div><h3>'+esc(o.deviceName)+'</h3><p>'+esc(o.name)+'</p>'+btn('execution-use','选择设备',null,'data-node="'+n.id+'" data-device="'+o.deviceId+'" data-id="'+o.id+'"')+'</div></article>').join('')+'</div>'+(!app.deviceChoices.length?notice('暂无匹配的远端资源。请先加入共享画布，再让成员主动开放工作流。'):'')+btn('execution-devices','管理设备资源','settings'),'execution-choose');}
  function executionParameters(nodeId,offer){const n=graph.get(nodeId);if(!n||n.owner!=='me'||!offer)throw new Error('执行设备已失效，请重新选择');const fields=Object.entries(offer.parameters||{}).filter(([id,spec])=>/^[A-Za-z][A-Za-z0-9_.-]{0,79}$/.test(id)&&!/(key|secret|password|token|url|path|command|code|workflow)/i.test(id)&&['string','number','integer','boolean'].includes(spec?.type));app.executionConfig={nodeId,offer,fields};const previous=n.execution?.deviceId===offer.deviceId&&n.execution?.offerId===offer.id?n.execution.parameters||{}:{};let body=notice('执行设备：'+offer.deviceName+' · '+offer.name+'。仅显示此设备公开的参数；实际提交前会再次校验当前能力。');body+=fields.map(([id,spec],i)=>{const name='execution-param-'+i,value=previous[id]??spec.default??'',label=esc(id);if(Array.isArray(spec.enum))return select(name,label,[['','未设置（使用设备默认）'],...spec.enum.map((v,index)=>['option-'+index,String(v)])],(Object.hasOwn(previous,id)||spec.default!==undefined)&&spec.enum.includes(value)?'option-'+spec.enum.indexOf(value):'');if(spec.type==='boolean')return select(name,label,[['','未设置（使用设备默认）'],['true','是'],['false','否']],value);return input(name,label,value,spec.type==='string'?'text':'number',(Number.isFinite(spec.minimum)?'min="'+spec.minimum+'" ':'')+(Number.isFinite(spec.maximum)?'max="'+spec.maximum+'" ':'')+(spec.type==='integer'?'step="1" ':spec.type==='number'?'step="any" ':'')+(spec.type==='string'?'maxlength="'+(spec.maxLength||10000)+'"':''));}).join('');if(!fields.length)body+=notice('此工作流没有公开可调参数，将使用执行设备的配置。');show('执行参数',form('execution-parameters',body,'保存执行选择'),'execution-parameters');}
  const accountProviders=new Set(['codex','image2','openai-compatible','runninghub']);
  function executionOfferFields(){const selectResource=$('[data-desktop-form="execution-offer"] [name="capability"]'),index=Number(selectResource.value),resource=app.executionCapabilities.workflows[index];if(!resource)throw new Error('请重新选择可用资源');$('#execution-offer-kind').innerHTML=select('kind','输出类型',resource.kinds.map(kind=>[kind,types[kind]?.name||kind]),resource.kinds[0]);$('#execution-account-consent').innerHTML=accountProviders.has(resource.provider)?'<label class="row"><input type="checkbox" name="allowAccountUsage" required>我允许成员消耗本设备账号的额度或费用</label>':notice('此资源使用本设备的本地模型／工作流。');}
  async function executionShare(){const data=await call('execution.capabilities'),providers=new Map((data.providers||[{id:'comfyui',available:data.available}]).map(p=>[p.id,p]));const workflows=(data.workflows||[]).map(w=>({...w,provider:w.provider||'comfyui',kinds:(w.kinds||[]).filter(k=>['image','video','audio','text'].includes(k))})).filter(w=>providers.get(w.provider)?.available&&w.kinds.length);app.executionCapabilities={...data,workflows};const reasons=(data.providers||[]).filter(p=>!p.available).map(p=>'<p class="muted">'+esc(sourceNames[p.id]||p.id)+'：'+esc(p.reason||'尚未配置或不可用')+'</p>').join(''),warning=notice('仅开放你主动选择的生成能力。请求使用设备主人的模型、账号和额度；私人 Agent 对话、画布工具和凭据不共享。改变连接或模型后，需要重新确认开放。');if(!workflows.length){show('开放本机执行资源',warning+notice('当前没有已配置且可用的执行资源，请先在连接和节点配置中完成设置。')+reasons+btn('connections','检查连接','link'),'execution-offer');return;}show('开放本机执行资源',form('execution-offer',select('capability','已配置的执行资源',workflows.map((w,index)=>[String(index),(sourceNames[w.provider]||w.provider)+' · '+w.name]),'0')+'<div id="execution-offer-kind"></div>'+input('members','仅允许成员完整 ID（逗号分隔；留空为会话成员）')+warning+'<div id="execution-account-consent"></div>','确认开放')+reasons,'execution-offer');executionOfferFields();}
  const chatScope=value=>value?(value.projectDir||'')+'|'+(value.canvasId||value.id||''):'';
  const chatOrigin=chat=>chat?.turns?.at(-1)||chat;
  const chatScopeName=value=>value?(value.canvasName||value.name||value.canvasId||value.id||'画布')+' · '+(value.projectDir||'').split(/[\\/]/).pop():'未打开画布';
  function resetChatDisplay({clearInput=false}={}){app.chatViewVersion=(app.chatViewVersion||0)+1;app.threadId=null;app.messages=[];app.chatRecord=null;app.chatScopeApproved=null;app.chatNotice='';if(clearInput)$('#chat-input').value='';renderChat();}
  function displayChat(record){app.chatViewVersion=(app.chatViewVersion||0)+1;app.chatRecord=C.clone(record);app.threadId=record.threadId;app.messages=C.clone(record.messages||[]);app.chatScopeApproved=null;app.chatNotice='';renderChat();}
  function chatBlocked(){return !!(app.chatSending||app.chatRecovering||app.chatStatus?.active||app.chatStatus?.pendingResults);}
  function renderChat(){
    const status=app.chatStatus||{},origin=chatOrigin(app.chatRecord),different=origin&&chatScope(origin)!==chatScope(app.current);app.busyChat=chatBlocked();
    $('#chat-messages').innerHTML=app.messages.map(m=>'<div class="chat-message '+(m.role==='assistant'?'system':'')+'">'+esc(m.text)+'</div>').join('');$('.agent-empty').hidden=app.messages.length>0;$('#agent > header > strong').textContent=app.chatRecord?.title||'新对话';
    const lines=[];if(origin){lines.push('历史回合来自：'+chatScopeName(origin));const skills=origin.skills||[];if(skills.length)lines.push('当时的方法：'+skills.map(s=>(s.name||s.id)+' · v'+(s.revision||s.version||1)+(s.sha256?' · '+s.sha256.slice(0,8):'')).join('；'));lines.push('本次继续将作用于：'+chatScopeName(app.current)+'。历史素材与方法不会自动重新选中。');}
    if(app.chatNotice)lines.push(app.chatNotice);const context=$('#agent-context');context.hidden=!lines.length;context.innerHTML=lines.map(line=>'<div>'+esc(line)+'</div>').join('')+(different?'<div class="row">'+btn('agent-open-canvas','切回原画布','workflow')+'</div>':'');
    const needsCheck=status.phase==='unknown'||Number(status.pendingResults)>0;$('#agent-recovery').hidden=!needsCheck;$('#agent-recovery [data-action="agent-reconcile"]').disabled=!!app.chatRecovering;$('.send').disabled=app.busyChat||!app.current;$('#agent [data-action="agent-stop"]').disabled=!(status.active||app.chatSending);
    const elsewhere=(status.canvasId&&chatScope(status)!==chatScope(app.current))||(app.chatSendScope&&app.chatSendScope!==chatScope(app.current));
    $('.agent-status').textContent=app.chatRecovering?'正在核对原回合，不重新发送…':needsCheck?(status.pendingResults?'回答已取得 · 等待保存原聊天':'原回合状态未确认 · 请核对原回合'):status.active||app.chatSending?(elsewhere?'另一画布的私人回合仍在处理 · 结果保留原归属':app.chatProgress||'Codex 正在处理…'):app.chatNotice|| (app.status?.providers?.codex?.ready?'本机 Codex · 已连接':'本机 Codex · '+(app.status?.providers?.codex?.reason||'尚未连接'));
    const body=$('.agent-body');body.scrollTop=body.scrollHeight;
  }
  async function refreshChatStatus(){const status=await call('agent.status');app.chatStatus=status;clearTimeout(app.chatStatusTimer);renderChat();if(status.active&&status.phase!=='unknown')app.chatStatusTimer=setTimeout(()=>refreshChatStatus().catch(error),1500);return status;}
  async function sendChat(){
    const input=$('#chat-input'),text=input.value.trim();await refreshChatStatus();if(!text||chatBlocked())return;const origin=chatOrigin(app.chatRecord),scope=chatScope(app.current);
    if(origin&&chatScope(origin)!==scope&&app.chatScopeApproved!==scope){show('确认本次对话作用范围',notice('历史回合来自 '+chatScopeName(origin)+'。本次继续只会引用和操作当前画布 '+chatScopeName(app.current)+'；不会自动切换或引用原画布素材。')+'<div class="panel-footer">'+btn('close-panel','取消')+btn('agent-open-canvas','切回原画布')+btn('agent-continue-current','在当前画布继续',null,'class="primary"')+'</div>','chat-scope');return;}
    const version=app.chatViewVersion||0,args={text,threadId:app.threadId,skillIds:[...app.skillIds],nodeIds:[...ui.selected]};app.chatSending=true;app.chatSendScope=scope;app.chatNotice='';app.chatProgress='正在准备当前画布引用…';renderChat();
    try{await sync();if(scope!==chatScope(app.current)||(app.chatViewVersion||0)!==version)throw new Error('显示或画布已切换，本条消息未发送，输入仍保留');app.messages.push({role:'user',text});renderChat();const response=await call('agent.send',args),history=await call('agent.history'),record=history.find(c=>c.id===response.chatId);
      if(scope===chatScope(app.current)&&(app.chatViewVersion||0)===version){if(record)displayChat(record);if(input.value.trim()===text)input.value='';if(JSON.stringify(app.skillIds)===JSON.stringify(args.skillIds))app.skillIds=[];}else{app.chatNotice='另一显示中的回答已保存到原聊天，请从历史查看。';toast(app.chatNotice);}
    }catch(e){if(scope===chatScope(app.current)&&(app.chatViewVersion||0)===version)app.chatNotice='本轮尚未完成：'+e.message+'。输入已保留；若状态未确认，请先核对原回合，不要重复发送。';else{app.chatNotice='原回合仍保留在私人历史中，请核对原回合；未添加到当前聊天。';toast(app.chatNotice);}}
    finally{app.chatSending=false;app.chatSendScope=null;app.chatProgress='';await refreshChatStatus();}
  }
  async function reconcileChat(){if(app.chatRecovering)return;const version=app.chatViewVersion||0,scope=chatScope(app.current),shownId=app.chatRecord?.id;app.chatRecovering=true;renderChat();try{const response=await call('agent.reconcile');if(response.chatId){const history=await call('agent.history'),record=history.find(c=>c.id===response.chatId);if(record&&(app.chatViewVersion||0)===version&&(shownId===record.id||chatScope(chatOrigin(record))===scope))displayChat(record);else{app.chatNotice='原回合已核对并保存到私人历史；当前画布与显示没有切换。';toast(app.chatNotice);}}else app.chatNotice=response.message|| (response.state==='idle'?'没有待核对的私人回合':'原回合仍待确认，未重新发送。');}catch(e){app.chatNotice='核对尚未完成：'+e.message+'。原记录保留，不重新发送。';}finally{app.chatRecovering=false;await refreshChatStatus();}}
  async function refresh(){const status=await call('app.status');app.status=status;app.settings=status.settings;await refreshSkills();await refreshTools();app.tasks=await call('task.list');if(status.current){apply(status.current);app.history=await call('history.list');}else{graph.state={version:5,nodes:[],edges:[],groups:[],assets:[],view:{x:60,y:130,k:1},seq:0,chat:[],settings:{saveMinutes:5,maxSnapshots:100}};ui.selected.clear();C.render();await projectPage();}await refreshChatStatus();$('#save-status').textContent=app.current?'已打开本地项目':'请新建或打开项目';}
