    show(n.title,(n.sourceAssetId?notice('基于实际时间取样的代表帧分析，不假称已精确识别所有镜头切点。可调整时间、拆分和合并；重新分析会生成新版本，保留本表人工修改。'):'<div class="step-bar"><span class="active">① 确认镜头</span><span>② 准备资产</span><span>③ 合成提示词</span></div>')+'<div class="row between"><p>'+n.shots.length+' 个镜头</p>'+btn('download-script','导出含截图 Excel','download','data-node="'+n.id+'"')+'</div><div class="table-scroll"><table><thead><tr><th>镜号</th>'+(n.sourceAssetId?'<th>代表截图</th>':'')+fields.map(([,label])=>'<th>'+label+'</th>').join('')+'<th>操作</th></tr></thead><tbody>'+n.shots.map((s,i)=>'<tr><td>'+String(i+1).padStart(2,'0')+'</td>'+(n.sourceAssetId?'<td>'+(s.frame?'<button data-action="shot-frame" data-index="'+i+'"><img src="'+esc(s.frame)+'" alt="实际代表帧"></button>':'暂无')+'</td>':'')+fields.map(([key])=>'<td '+(!readonly?'contenteditable="plaintext-only"':'')+' data-shot="'+i+'" data-field="'+key+'">'+esc(s[key]||'')+'</td>').join('')+'<td>'+btn('shot-to-canvas','取用文字与截图',null,'data-index="'+i+'"')+(!readonly?btn('shot-split','拆分',null,'data-index="'+i+'"')+btn('shot-merge','合并下一行',null,'data-index="'+i+'"'):'')+'</td></tr>').join('')+'</tbody></table></div><div class="panel-footer">'+(!readonly?btn('add-shot','添加镜头','plus')+btn('prepare-assets','识别资产 →'):'')+btn('close-panel','完成编辑','check','class="primary"')+'</div>','storyboard');
