    'storage-management':async()=>{const report=await call('storage.inspect');const mb=n=>(n/1024**2).toFixed(1)+' MB';show('存储管理','<div class="form-row"><label>本画布素材（绝不自动删除）</label><span>'+report.assets.count+' 份 · '+mb(report.assets.bytes)+'</span></div><div class="form-row"><label>自动保存版本</label><span>'+report.autosaves.count+' 份</span></div><div class="form-row"><label>日常日志 / 关键错误</label><span>'+mb(report.logs.bytes)+' / '+mb(report.logs.criticalBytes)+'</span></div><div class="form-row"><label>任务冻结输入（保留）</label><span>'+mb(report.taskInputs.bytes)+'</span></div><div class="form-row"><label>可重建的生成指令缓存</label><span>'+report.cache.entries+' 项 · '+mb(report.cache.bytes)+'</span></div>'+form('cache-trim',input('keepMB','保留缓存容量（MB）',256,'number','min="0"')+notice('仅清理已成功的风格指令缓存，移入本机缓存回收区。重新使用被清理的方法会再次调用模型并消耗额度；素材、任务输入和关键错误不动。'),'清理超出容量的缓存'),'storage');},
    'annotate-tool':async()=>{const n=graph.get(ui.context);if(!n?.assetId)throw new Error('请选择已有素材');const nodeId=n.id,sourceAssetId=n.assetId,canvasId=app.current?.id,projectDir=app.current?.projectDir,toolId=app.toolId||app.toolName,values=Object.fromEntries(new FormData(document.querySelector('[data-desktop-form="tool"]')));delete values.annotationAssetId;delete values.annotationTime;let url=n.asset,time=Number(values.start)||0;if(n.type==='video'||n.outputType==='video'){const player=$('#tool-preview');time=Number.isFinite(player?.currentTime)?player.currentTime:time;const frame=await call('media.annotationFrame',{sourceAssetId,time});url=frame.url;time=frame.time;values.start=time;}const restore=async()=>{await toolPage(nodeId,toolId);for(const [key,value]of Object.entries(values)){const field=document.querySelector('[data-desktop-form="tool"] [name="'+CSS.escape(key)+'"]');if(field)field.value=value;}};await window.CreateMoreAnnotation.open({url,title:n.title+' · 标注',onCancel:restore,onSave:async data=>{await sync();if(app.current?.id!==canvasId||app.current?.projectDir!==projectDir||graph.get(nodeId)?.assetId!==sourceAssetId)throw new Error('原素材或画布已改变，请重新选择并标注');const result=await call('asset.annotate',{...data,sourceAssetId});apply(result.view);app.annotation={nodeId,toolId,assetId:result.assetId,time,sourceAssetId,canvasId,projectDir};ui.staged=false;await restore();}});},
