    const id=b.dataset.node||ui.context||[...ui.selected][0],n=graph.get(id);const mutating=['rename','edit-text','spec','add-shot','remove-edge','collapse','ungroup','rename-group'];if(n&&n.owner!=='me'&&mutating.includes(name)){event.preventDefault();event.stopImmediatePropagation();toast('其他成员内容只读；可复制后编辑自己的副本。');return;}
